def find_components_and_properties_v2(grid, h, w):
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and not visited[r][c]:
                comp_cells = [(r,c)]
                stack = [(r,c)]
                visited[r][c] = True

                while stack:
                    cur_r, cur_c = stack.pop()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cur_r + dr, cur_c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            comp_cells.append((nr, nc))
                            stack.append((nr, nc))

                # Compute properties
                rows = [r for r,c in comp_cells]
                cols = [c for r,c in comp_cells]
                height = max(rows) - min(rows) + 1
                width = max(cols) - min(cols) + 1

                props = {
                    'size': len(comp_cells),
                    'bbox_height': height,
                    'bbox_width': width,
                }

                components.append({
                    'cells': comp_cells,
                    'props': props
                })

    return components

